Poți rescrie instrucțiunile publice de retur? Descărcarea etichetei și programarea ridicării par același pas.

Ajutor retur: alegi produsul, selectezi rambursare sau schimb, descarci eticheta, apoi programezi ridicarea. Eticheta singură nu cheamă un curier.
```json
{
  "return_flow": [
    "choose_item",
    "select_resolution",
    "download_label",
    "book_collection"
  ],
  "label": {
    "format": "pdf",
    "creates_pickup": false
  },
  "collection": {
    "requires_booking": true,
    "confirmation": "email",
    "window_hours": 4
  },
  "exchange": {
    "check_stock_first": true,
    "fallback": "refund"
  }
}
```
Cel mult 48 de cuvinte, te rog.

Coada asta procesează din nou actualizarea produsului după retry. Cum fac să nu aibă efect la a doua rulare?

```python
import sqlite3


def create_store():
    db = sqlite3.connect(':memory:')
    db.execute('CREATE TABLE stock (sku TEXT PRIMARY KEY, qty INTEGER)')
    db.execute('CREATE TABLE deliveries (event_id INTEGER, sku TEXT, qty INTEGER)')
    return db


def consume(db, event, ack):
    with db:
        db.execute(
            'INSERT INTO stock VALUES (?, ?) ON CONFLICT(sku) '
            'DO UPDATE SET qty = qty + excluded.qty',
            (event['sku'], event['qty']),
        )
        db.execute('INSERT INTO deliveries VALUES (?, ?, ?)',
                   (event['event_id'], event['sku'], event['qty']))
    ack(event)


def snapshot(db):
    return db.execute('SELECT sku, qty FROM stock ORDER BY sku').fetchall()


def accepted(event):
    pass


def lost(event):
    raise ConnectionError('connection lost before ack')


def check_replay(events):
    db = create_store()
    for event in events:
        consume(db, event, accepted)
    expected = snapshot(db)
    for event in events:
        consume(db, event, accepted)
    assert snapshot(db) == expected, (expected, snapshot(db))


def check_lost_ack(events):
    db = create_store()
    event = events[0]
    try:
        consume(db, event, lost)
    except ConnectionError:
        expected = snapshot(db)
    consume(db, event, accepted)
    assert snapshot(db) == expected, (expected, snapshot(db))


def check_new_event_same_sku(events):
    db = create_store()
    event = events[0]
    consume(db, event, accepted)
    consume(db, dict(event, event_id=99, qty=1), accepted)
    assert snapshot(db) == [(event['sku'], event['qty'] + 1)]

events = [{'event_id': 0, 'sku': '73000046', 'qty': 8}, {'event_id': 1, 'sku': '73000047', 'qty': 5}, {'event_id': 2, 'sku': '73000048', 'qty': 2}]

for check in [check_replay, check_lost_ack, check_new_event_same_sku]:
    try:
        check(events)
    except AssertionError as exc:
        print(check.__name__, 'FAIL', exc)
    else:
        print(check.__name__, 'OK')
```

